package xyz.shuncongci.leica

import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.junit.runners.Parameterized
import java.io.*
import java.nio.file.Files
import xyz.shuncongci.leica.LegendaryMath.Frame

/** Exact Float32 fixtures generated by ProbeRadianceGolden using the FROZEN 67 binary.
 * Sparse sources at reflected borders, signed HDR, all-zero radiance and band boundaries. */
@RunWith(Parameterized::class)
class RadianceExactSpeedTest(private val case:Int,private val band:Int) {
    companion object { @JvmStatic @Parameterized.Parameters(name="case{0}-band{1}") fun cases()=(0..7).flatMap{c->listOf(1,17,128).map{b->arrayOf(c,b)}} }
    private fun fixture(name:String):Frame {
        val path="/exact-radiance67/case$case/$name.f32"
        DataInputStream(javaClass.getResourceAsStream(path)?:error(path)).use{f->
            require(f.readInt()==0x4c435031);val w=f.readInt();val h=f.readInt();val c=f.readInt()
            return Frame(w,h,c,FloatArray(w*h*c){f.readFloat()}).also{check(f.read()==-1)}
        }
    }
    @Test fun matches67RawFloatBits(){
        val root=Files.createTempDirectory("exact-radiance-").toFile();val co=fixture("coc");val files=arrayListOf<BokehFloatFile>()
        try {
            val inputs=(0..1).map{g->val src=fixture("source$g");BokehFloatFile.create(File(root,"input$g"),co.w,co.h,3).also{files.add(it);it.put(src,it.whole,Cancel())}}
            val outputs=(0..1).map{g->BokehFloatFile.create(File(root,"color$g"),co.w,co.h,3).also(files::add)}
            val fronts=(0..1).map{g->BokehFloatFile.create(File(root,"front$g"),co.w,co.h,3).also(files::add)}
            StreamingLightScatter.Pupils(co.w,co.h,2.8f,root).use{pupils->RadianceTransport.run(inputs,co,2.8f,Cancel(),outputs,fronts,booleanArrayOf(false,true),pupils,band)}
            for(g in 0..1)for((name,actual) in listOf("color" to outputs[g],"front" to fronts[g])){
                val want=fixture("$name$g").data;val got=actual.read(actual.whole,Cancel()).data
                assertEquals(want.size,got.size);for(i in want.indices)assertEquals("$name$g@$i",want[i].toRawBits(),got[i].toRawBits())
            }
        }finally{files.forEach{it.close()};root.walkBottomUp().forEach{it.delete()}}
    }
}
